INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'bn'), 'A1', 'greetings', 'Greetings', 'Greet people politely and introduce yourself in Bengali.', 'You''ve just rented a flat in Salt Lake. Mitra mashima, your landlady, comes to say hello.', '“Nomoshkar” is the respectful hello. Use “apni” (polite “you”) with elders and strangers, and verbs ending in -un or -en: “bolun”, “kemon achhen?”. Older women are “mashima” (aunty), older men “kaku”, and anyone a little older “dada” or “didi”.', 1, 'published', datetime('now'), datetime('now'), 1);
