INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'bn'), 'A1', 'transport', 'Transport', 'Take a yellow taxi by the meter, and the metro.', 'You''ve arrived at Howrah Station and need to get to Park Street.', 'Kolkata''s yellow taxis should go by the meter: ask “Meter-e jaben to?” before you get in, and expect some drivers to ask for a little extra or refuse short trips. Autos run on fixed shared routes, and the metro (India''s first) runs north–south from Dakshineswar to Kavi Subhash; the Green Line goes under the Hooghly to Howrah and on to Salt Lake.', 2, 'published', datetime('now'), datetime('now'), 1);
