INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'bn'), 'A1', 'food', 'Food', 'Order a kathi roll, tea in a clay cup and the famous sweets.', 'An evening snack at a roll stall near Park Street.', 'Kolkata''s street food: kathi rolls, phuchka (its pani puri) and ghugni; then the sweets, roshogolla, sandesh and mishti doi. Tea comes in a “bhaar”, a small clay cup. “Jhal kom” means less chilli.', 3, 'published', datetime('now'), datetime('now'), 1);
