INSERT INTO grammar_topics(language_id, cefr_code, slug, sort_order) VALUES ((SELECT id FROM languages WHERE code = 'bn'), 'A1', 'polite-requests', 1);
INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'bn') AND slug = 'polite-requests'), (SELECT id FROM languages WHERE code = 'en'), 'Polite requests: “din”, “korun”, “bolun”', 'Bengali asks politely with the “apni” (you, polite) form of the verb, which ends in -un or -en: “din” (please give), “korun” (please do), “bolun” (please say), “thamun” (please stop). With friends the “tumi” form is used: “dao”, “koro”, “bolo”.');
