INSERT INTO grammar_topics(language_id, cefr_code, slug, sort_order) VALUES ((SELECT id FROM languages WHERE code = 'bn'), 'A1', 'questions', 2);
INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'bn') AND slug = 'questions'), (SELECT id FROM languages WHERE code = 'en'), 'Questions: “ki”, “koto”, “kothay”', 'A yes-no question is a statement said with a rising voice, often with “ki” after the subject: “Tumi ki Kolkatar-i?” (are you from Kolkata?). A question word stays where the answer would go: “Etar daam koto?” (this one''s price, how much?), “Metro station kothay?”.');
